USE portfolio_muhzy;
CREATE TABLE IF NOT EXISTS hobbies (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL,description VARCHAR(180) NOT NULL DEFAULT '',sort_order INT NOT NULL DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS page_views (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,visitor_hash CHAR(64) NOT NULL,page_path VARCHAR(190) NOT NULL DEFAULT '/',device_type ENUM('Mobile','Desktop','Tablet','Other') NOT NULL DEFAULT 'Other',visited_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,INDEX idx_visited_at(visited_at),INDEX idx_visitor_date(visitor_hash,visited_at)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS visitor_messages (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NULL DEFAULT NULL,email VARCHAR(190) NULL DEFAULT NULL,subject VARCHAR(180) NULL DEFAULT NULL,message TEXT NOT NULL,is_read TINYINT(1) NOT NULL DEFAULT 0,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,INDEX idx_message_read(is_read,created_at)) ENGINE=InnoDB;
ALTER TABLE visitor_messages MODIFY name VARCHAR(100) NULL DEFAULT NULL,MODIFY email VARCHAR(190) NULL DEFAULT NULL,MODIFY subject VARCHAR(180) NULL DEFAULT NULL;
